list_order_custom_fields.code:
final response = await client.orderCustomFields
    .listOrderCustomFields(queryParams: {'sort': 'label', 'dir': 'asc'});
final fields = (response.map as Map)['order_custom_fields'] as List;
for (final field in fields) {
  print('${(field as Map)['id']} ${field['label']} ${field['field_type']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

count_order_custom_fields.code:
final response = await client.orderCustomFields
    .countOrderCustomFields(queryParams: {'filterBy': 'date'});
print((response.map as Map)['count']);

get_order_custom_field.code:
final response = await client.orderCustomFields.getOrderCustomField(42);
final field = (response.map as Map)['order_custom_field'] as Map;
print('${field['label']} ${field['field_type']} ${field['is_required']}');
print('${field['placeholder']} ${field['hover_text']}');

validate_order_custom_field_timeslot.code:
